"use strict";(self.webpackChunkpersonal_blog_of_alexander_trauzzi=self.webpackChunkpersonal_blog_of_alexander_trauzzi||[]).push([[610],{1063:function(e,t,n){n.r(t),n.d(t,{default:function(){return u}});var a=n(8453),o=n(6540);function i(e){const t=Object.assign({h2:"h2",p:"p",a:"a",em:"em",blockquote:"blockquote",h3:"h3",code:"code",ul:"ul",li:"li",br:"br",pre:"pre"},(0,a.R)(),e.components);return o.createElement(o.Fragment,null,o.createElement(t.h2,null,"It's something of a wonder, really"),"\n",o.createElement(t.p,null,"I closed out 2025 with ",o.createElement(t.a,{href:"/state-of-tech-end-of-2025"},"a post")," talking about my feelings towards AI, with more questions\nthan answers, and a mix of skepticism and curiosity."),"\n",o.createElement(t.p,null,"Fast-forward half a year, and I doubt I could have predicted how much my habits and perspectives would have changed. I\nwill save the full retrospective for December of this year, but I have to say, the ",o.createElement(t.a,{href:"https://www.youtube.com/@TheTechReportTR"},"culture and coverage of all this"),"\n",o.createElement(t.a,{href:"https://www.youtube.com/@atmoio"},"really moves at a breakneck pace"),"! I'm also pleased to see that ",o.createElement(t.em,null,"some")," of my\npredictions were roughly in the ballpark of what's happened this year so far as well."),"\n",o.createElement(t.blockquote,null,"\n",o.createElement(t.p,null,"✍ Though I will remind everyone, my blog posts remain hand-authored...for now."),"\n"),"\n",o.createElement(t.h2,null,"Briefly, Vertical Slicing and Transaction Scripts"),"\n",o.createElement(t.p,null,"Prior to the current AI era, I'd been interested in applying vertical slicing, relaxing of DRY, transaction scripts and\nshallow structuring in dotnet projects. Especially as presented by ",o.createElement(t.a,{href:"https://www.youtube.com/@CodeOpinion"},"Derek Comartin of CodeOpinion"),";\nWho I will always waste no opportunity to mention in my writings and conversations."),"\n",o.createElement(t.h3,null,"Vertical Slicing"),"\n",o.createElement(t.p,null,"The main thing with vertical slicing that I enjoy is how it's centered around grouping functionality according to\nbusiness domain.  It's absolutely an art form past a certain point, but getting started I've found really centers on\nresisting the urge to group namespaces, modules and files by their commonalities at a language or pattern-level."),"\n",o.createElement(t.p,null,"So, instead of having a ",o.createElement(t.code,null,"Models/")," directory (and more importantly, corresponding namespace) at the toplevel of your\nprojects, try one or both of:"),"\n",o.createElement(t.ul,null,"\n",o.createElement(t.li,null,"Simply not having sub-namespaces at all, and keeping everything at the root"),"\n",o.createElement(t.li,null,"Creating a directory to represent the area of functionality in a tear-away fashion"),"\n"),"\n",o.createElement(t.p,null,"One other neat mind-trick I like to use is to imagine two people working on the same codebase, but in different areas.\nWhat kind of filesystem structure would help ensure that their changesets stand the best chance of never colliding?\nHow much easier could I make it so that when they merge their changes, the likelihood of a conflict is minimized?"),"\n",o.createElement(t.h3,null,"Transaction Scripts"),"\n",o.createElement(t.p,null,"There might be some temptation to frame this as a technology concept, but it really isn't.  Once most\npeople sort out ",o.createElement(t.a,{href:"https://martinfowler.com/eaaCatalog/transactionScript.html"},"what transaction scripts are"),', they tend\nto think either "oh, I already do that!" or "I use services for logic."'),"\n",o.createElement(t.p,null,'Though I will say that they do defy some definition, transaction scripts are just "start at the top,\nand run to the end."  It takes a deep familiarity with your language and framework ecosystems to implement\ntransaction scripts in a way that\'s spiritually true.'),"\n",o.createElement(t.p,null,"Thinking about every language and framework I've worked in, there's always a canonical starting point.",o.createElement(t.br),"\n","I don't even consider it a hot take, though I know many people will balk at what sounds like my rejection of\na very widely embraced philosophy on diversity: There is usually - at best - a handful of \"advisable ways\"\nto go about doing things.  Though I don't think in practice it's as controversial as it sounds."),"\n",o.createElement(t.blockquote,null,"\n",o.createElement(t.p,null,"You've almost certainly heard the above assertion in the form of \"don't fight your framework\"..."),"\n"),"\n",o.createElement(t.p,null,'When we try to apply shallow interpretations of patterns and best practices, we create what are called inner\nplatforms. Or as some might prefer to say, "reinvent the wheel". The inherent danger in this is that each deviation\nfrom idiomatic language or framework ecosystem norms puts your broader application design into question.'),"\n",o.createElement(t.p,null,"As someone who has spent years toiling on a spiritual journey through various interpretations of n-tier, onion skin,\nhexagonal, rhomboid and trapezoidal architectures, I've found transaction scripts combined with a less dogmatic view on\nDRY to be liberating."),"\n",o.createElement(t.p,null,"Taken in combination with vertical slicing, transaction scripts represent a kind of cognitive reset switch.  Not just\nin your habits as a professional, but also in your navigation within any given project."),"\n",o.createElement(t.h2,null,"Structure and Scope"),"\n",o.createElement(t.p,null,"Fundamentally, the more context you can acquire at any given point in a codebase, and the speed which you can then\nshed it to make room while moving around; The more effective you can be and the more scope you can cut through."),"\n",o.createElement(t.p,null,"I've name-dropped quite a few concepts here, each of which might seem appealing but also too abstract to simply take\nas-defined and be successful.  But once you disabuse yourself of the ",o.createElement(t.em,null,"shoulds")," and ",o.createElement(t.em,null,"shouldn'ts")," you might have acquired\nover the last ten (or more!) years... It clicks!"),"\n",o.createElement(t.h2,null,"What's up AI?"),"\n",o.createElement(t.p,null,"Imagine my surprise then, when I realized that my application of project structure norms, aligned to my framework of\nchoice started to pay dividends as I began dabbling with having AI in my development flow!"),"\n",o.createElement(t.p,null,"It's not so much that I am going to try and take credit for enabling AI to work on my codebase at all. The fact is,\nno matter how we feel about LLMs today, both hosted and locally-runnable models have become very capable."),"\n",o.createElement(t.p,null,"If you take that growing capability and treat it like another member of your project however - with all the attendant\nobligations to ensure you are communicating effectively - the benefits really start to stack.  That's where the premise\nof this blog post comes from.  It kicks in when you take SDLC techniques that make it easier for humans to collaborate\nand make them available to LLMs as well."),"\n",o.createElement(t.p,null,"Rather than having to stuff my codebase up with ",o.createElement(t.code,null,"AGENTS.md")," files, the existing application code serves to\nsignpost LLMs through any choices being made."),"\n",o.createElement(t.blockquote,null,"\n",o.createElement(t.p,null,"They are, after all, excellent pattern recognizers!"),"\n"),"\n",o.createElement(t.p,null,"Again, I'm not proposing that any of this is revolutionary, but it's reassuring to know that good fundamentals can\nstill matter as we pass through a lot of uncertainty around what direction the industry is going in.  It's nice to find\nways where quality and care can in fact yield velocity."),"\n",o.createElement(t.h2,null,"What does it look like?"),"\n",o.createElement(t.p,null,'I\'m probably not going to be able to explain this in a way that will address every possible angle and question.\nSomewhat disappointingly, this part of the post is just going to be another run-of-the-mill\n"how I structure my solutions in dotnet" showcase.'),"\n",o.createElement(t.p,null,"But yeah, you know what, ",o.createElement(t.em,null,"what the hey"),":"),"\n",o.createElement(t.pre,null,o.createElement(t.code,null,"Solution/\n    AppHost/\n    ServiceDefaults/\n    Common.ApplicationGraph/\n    Common.Domain/\n    Api/\n        Discovery/\n        BusinessArea1/\n            WireType/\n            BusinessArea1EndpointExtensions.cs <- Transaction scripts\n        BusinessArea2/\n            WireType/\n            BusinessArea2EndpointExtensions.cs <- Transaction scripts\n        BusinessArea3/\n            WireType/\n            BusinessArea3EndpointExtensions.cs <- Transaction scripts\n        CrossCuttingConcern1.cs\n        CrossCuttingConcern2.cs\n        Program.cs        \n    Worker/\n        BusinessArea1/\n            BusinessArea1Workflow.cs\n            BusinessArea1WorkflowActivity1.cs <- Transaction script\n            BusinessArea1WorkflowActivity2.cs <- Transaction script\n            BusinessArea1WorkflowActivity3.cs <- Transaction script\n        BusienssArea4/\n            BusinessArea4Workflow.cs\n            BusinessArea4WorkflowActivity1.cs <- Transaction script\n            BusinessArea4WorkflowActivity2.cs <- Transaction script\n            BusinessArea4WorkflowActivity3.cs <- Transaction script\n        Program.cs\n    Worker.Integrations.Domain/\n        ...\n    Notifications/\n        Program.cs\n    Notifications.Domain/\n        ...\n    Notifications.WireTypes/\n    Domain/\n        Model1.cs\n        Model2.cs\n        Model3.cs\n        Model4.cs\n        DomainDbContext.cs\n    Domain.Migrations/\n        ...\n    Domain.Test.Slow/\n    Domain.Test.Fast/\n    docs/\n        adrs/\n        conventions/\n")),"\n",o.createElement(t.p,null,"...and honestly, like you'd expect, this is continuously evolving.  What you won't see in this project structure is\nwhat I refer to as n-tier slop. There are no services, no repository layers and no ",o.createElement(t.code,null,"*Helper.cs")," files.  Generally\nspeaking, everything that needs to be expressed can be either by integrating with the framework or the language."),"\n",o.createElement(t.p,null,"The one main thing worth calling out is that the transaction scripts are where all your control flow lives. I cannot\nemphasize this enough.  This is something I know first-hand that many developers struggle with, as it's always\npossible to simply start authoring control code anywhere."),"\n",o.createElement(t.blockquote,null,"\n",o.createElement(t.p,null,'The PHP ecosystem has a saying "it\'s just PHP", which means if something is getting in your way, simply disregard\nany lifecycle you might be participating in, and go rogue.'),"\n"),"\n",o.createElement(t.p,null,"Once you understand that each operation against your system is atomic, you stop fretting over centralizing where\nyour logic lives or creating units of reuse.  My favourite contrived example is changing a users email.  There's an\nappreciable difference between a user changing their own email and an administrator forcing a change to it.  While both\nthose flows share a common destination - the ",o.createElement(t.code,null,"Email")," property on some ",o.createElement(t.code,null,"User")," entity - the code that enacts that change\ndoesn't by-nature need to be forced through a shared pinhole."),"\n",o.createElement(t.p,null,"That said, there are certain scenarios, particularly around data shape and consistency that do necessitate some\ncentralization.  And that is where your domain model comes in.  By restricting the centralization to areas where scope\nand control flow are de-facto forbidden, you structurally enforce simplicity."),"\n",o.createElement(t.p,null,'I could spend another ten pages on this and barely make a dent in "good project structure".\nEverything I\'ve described is intended to promote discoverability and simplicity.  The codebase should remain\ncognitively flat.  Not only in terms of the routines, but also structurally so that it always remains approachable.'),"\n",o.createElement(t.h2,null,"Bringing it back to AI"),"\n",o.createElement(t.p,null,"I'll close things out at this point as I'm hoping to keep this post medium-length. But I hope you can now see that\nby enforcing a structure that doesn't create ambiguity in where each concept lives, you can seed your codebase to allow\nboth humans and LLMs to collaborate and succeed."),"\n",o.createElement(t.p,null,"The only big thought I'd offer at this point is that we as an industry should explore which patterns are useful and\nwhich are dogma, driven by entrenched habits or worse, maladaptions stemming from two decades of framework antipatterns."))}var r=function(e){void 0===e&&(e={});const{wrapper:t}=Object.assign({},(0,a.R)(),e.components);return t?o.createElement(t,e,o.createElement(i,e)):i(e)},s=n(9200),l=n(5093),c=n.n(l);const h=e=>{let{data:t,pageContext:n,children:a}=e;const i=t.site.siteMetadata.title,r=t.mdx.frontmatter.title,l=c()(t.mdx.frontmatter.posted).format("LLLL"),h=t.package.version;return o.createElement(s.O,{title:i,showTitle:!1,pageTitle:r,byline:l,version:h},o.createElement("article",null,a))};function u(e){return o.createElement(h,e,o.createElement(r,e))}},8453:function(e,t,n){n.d(t,{R:function(){return r}});var a=n(6540);const o={},i=a.createContext(o);function r(e){const t=a.useContext(i);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}}}]);
